SELECT ID, TOOL_CODE, USER_ID, BORROW_TIME, RETURN_TIME, STATUS, OPERATOR_TYPE
FROM BORROW_RECORD
WHERE 1=1

    AND (USER_ID LIKE '%' || #{keyword} || '%')


    AND BORROW_TIME >= #{startTime}


    AND BORROW_TIME <= #{endTime}


    AND OPERATOR_TYPE = #{operatorType}

ORDER BY BORROW_TIME DESC
OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

SELECT COUNT(*)
FROM BORROW_RECORD
WHERE 1=1

    AND (USER_ID LIKE '%' || #{keyword} || '%')


    AND BORROW_TIME >= #{startTime}


    AND BORROW_TIME <= #{endTime}


    AND OPERATOR_TYPE = #{operatorType}
